const $=s=>document.querySelector(s),dialog=$('#dialog');let total=1450,p=110,f=43,c=156,quiet=false,toastTimer;
function show(html){$('#dialogBody').innerHTML=html;if(!dialog.open)dialog.showModal()}
$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function update(){$('#cal').textContent=total.toLocaleString('uk-UA');$('#remaining').textContent=total<=2200?`Ще ${2200-total} ккал до цілі`:`На ${total-2200} ккал понад ціль`;$('#protein').innerHTML=p+' <small>г</small>';$('#fat').innerHTML=f+' <small>г</small>';$('#carbs').innerHTML=c+' <small>г</small>';$('#ringProgress').style.strokeDashoffset=641*(1-Math.min(total/2200,1))}
$('#add').onclick=()=>{show('<span class="eyebrow">ЗНАЙОМІ СТРАВИ</span><h2>Що сьогодні їв?</h2><p>Порції для прикладу. Обери одну або кілька страв.</p><label class="food"><span>Сирна запіканка<small>100 г · 140 ккал</small></span><input type="checkbox" value="0"></label><label class="food"><span>Кіш із лососем<small>50 г · 130 ккал</small></span><input type="checkbox" value="1"></label><label class="food"><span>Американо<small>Без додатків · 2 ккал</small></span><input type="checkbox" value="2"></label><button class="primary" id="confirmFood">Додати вибране</button>');$('#confirmFood').onclick=()=>{const selected=[...dialog.querySelectorAll('input:checked')];if(!selected.length){toast('Обери страву');return}const foods=[[140,16,4,10],[130,7,8,7],[2,0,0,0]];selected.forEach(el=>{const a=foods[+el.value];total+=a[0];p+=a[1];f+=a[2];c+=a[3]});update();dialog.close();toast('Додано до демонстраційного дня')}};
$('#nutrition').onclick=()=>show(`<span class="eyebrow">ХАРЧУВАННЯ · ДЕМО</span><h2>${total.toLocaleString('uk-UA')} ккал</h2><p>Денна ціль для прикладу — 2 200 ккал. Кільце відображає частку записаних калорій, а не оцінку здоров’я.</p><div class="reply">Білки: ${p} г<br>Жири: ${f} г<br>Вуглеводи: ${c} г</div><p>Записи зберігаються лише до оновлення сторінки.</p>`);
$('#insight').onclick=()=>show('<span class="eyebrow">ОГЛЯД ДНЯ · ДЕМО</span><h2>Усе починається з малого.</h2><div class="reply"><b>Що вдалося</b><br>Є запис сну та частина харчування.</div><div class="reply"><b>На що звернути увагу</b><br>Щоденник ще неповний. Додай решту їжі, коли буде зручно.</div><p>Це приклад підсумку. Персональний аналіз ще не підключений.</p>');
$('#workout').onclick=()=>{show('<span class="eyebrow">ПЛАН А · ДЕМО</span><h2>Тренування під рукою.</h2><p>Приклад запису підходу, а не рекомендоване навантаження.</p><div class="reply">Вправа з твоєї програми<br>Підхід 1 · 10 повторень<button class="primary" id="doneSet">Виконано</button></div>');$('#doneSet').onclick=e=>{e.target.textContent='Підхід відмічено';e.target.disabled=true}};
$('#chat').onsubmit=e=>{e.preventDefault();const text=$('#message').value.trim();if(!text)return;show('<span class="eyebrow">ПОМІЧНИК · ДЕМО</span><h2>Я поруч.</h2><div class="reply" id="userText"></div><p>Тут можна спробувати тихий режим: фон рухатиметься повільніше. ШІ та сповіщення ще не підключені.</p><button class="primary" id="quiet">'+(quiet?'Повернути звичайний темп':'Увімкнути тихий день')+'</button>');$('#userText').textContent=text;$('#quiet').onclick=()=>{quiet=!quiet;document.body.dataset.quiet=String(quiet);$('#companionTitle').textContent=quiet?'Сьогодні можна повільніше.':'У твоєму темпі.';$('#companionText').textContent=quiet?'Залишимо тільки найважливіше':'Погляньмо, як проходить день';dialog.close();toast(quiet?'Тихий день увімкнено':'Звичайний темп')};$('#message').value=''};
function panel(name){if(name==='Більше'){show('<span class="eyebrow">ТВІЙ ПРОСТІР</span><h2>Більше можливостей</h2><button class="menu-option" id="moreSleep">Сон<small>Подивитися демонстраційний запис</small></button><button class="menu-option" id="moreWorkout">Тренування<small>Відмітити підхід у прикладі</small></button><button class="menu-option" id="moreProfile">Про прототип<small>Що вже працює</small></button>');$('#moreSleep').onclick=()=>panel('Сон');$('#moreWorkout').onclick=()=>$('#workout').click();$('#moreProfile').onclick=()=>panel('Профіль');return}
const content={Сон:'7 год 20 хв · твоя оцінка: добре. Це демонстраційний ручний запис. Дані телефона або годинника не зчитуються.',Активність:'6 420 кроків — значення для демонстрації. Мініграфік показує приклад візуального оформлення, а не твою історію активності.',Прогрес:'Тут буде історія ваги, замірів і тренувань. Цей розділ поки не реалізований; зараз оцінюємо дизайн головного екрана.',Профіль:'Ember / 05 — інтерактивний дизайн-концепт. Можна додати їжу, відмітити підхід і спробувати тихий день. Дані не зберігаються після перезавантаження. Нейронний фон — художня анімація, він не відображає стан мозку чи серця.'};show('<span class="eyebrow">ДЕМОНСТРАЦІЯ</span><h2>'+name+'</h2><p>'+content[name]+'</p>')}
document.querySelectorAll('[data-panel]').forEach(el=>el.onclick=()=>panel(el.dataset.panel));$('#home').onclick=()=>{dialog.close();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};update();
